import { L, sandbox3, miss, notFound } from "./missing-30-endpoints.mjs";

const page = (s) => ({
	notFound,
	missing: s.missing || miss(s.missingMessage || "missing parameter"),
	sandbox: s.sandbox || sandbox3(s.sandParams, s.sandResults),
	...s,
});
const T = (en, es, fr, pt, ko, ja, zh) => L(en, es, fr, pt, ko, ja, zh);
const B = (en, es, fr, pt, ko, ja, zh) => L(en, es, fr, pt, ko, ja, zh);
const found = (name) =>
	T(
		[`200 with ${name} true when the list matches.`, "409 when fullName and the document pair are both absent.", `200 with ${name} false when the subject is simply not listed.`],
		[`200 con ${name} en true si la lista coincide.`, "409 si faltan fullName y el par de documento.", `200 con ${name} en false si el sujeto simplemente no está.`],
		[`200 avec ${name} à true si la liste correspond.`, "409 si fullName et la paire documentaire manquent.", `200 avec ${name} à false si le sujet n'est simplement pas listé.`],
		[`200 com ${name} true se a lista coincidir.`, "409 se faltarem fullName e o par de documento.", `200 com ${name} false se o sujeito simplesmente não estiver.`],
		[`목록이 일치하면 ${name}이 true인 200.`, "fullName과 문서 쌍이 없으면 409.", `단순히 없으면 ${name}이 false인 200.`],
		[`一覧が一致すると ${name} が true の 200。`, "fullName と文書の組が無いと 409。", `単に無ければ ${name} が false の 200。`],
		[`名单命中时 ${name} 为 true 的 200。`, "缺少 fullName 和证件组合时为 409。", `只是不在名单上时 ${name} 为 false 的 200。`],
	);

const watchP = [
	{ name: "fullName", type: "string", req: "cond", example: "SAMPLE NAME", desc: T("Name or, for a wallet list, the address. Enough on its own.", "Nombre o, en una lista de billeteras, la dirección. Basta por sí solo.", "Nom ou, pour une liste de portefeuilles, l'adresse. Il suffit seul.", "Nome ou, numa lista de carteiras, o endereço. Basta sozinho.", "이름. 지갑 목록이면 주소. 이것만으로 충분합니다.", "名前。ウォレット一覧なら住所。これだけで足ります。", "名称。钱包名单则放地址。只发它即可。") },
	{ name: "documentType", type: "string", req: "cond", example: "CPF", desc: T("Required with `documentNumber` when `fullName` is omitted. CPF without a name also needs `dateOfBirth`.", "Obligatorio con `documentNumber` si omite `fullName`. Un CPF sin nombre también exige `dateOfBirth`.", "Obligatoire avec `documentNumber` si `fullName` est omis. Un CPF sans nom exige aussi `dateOfBirth`.", "Obrigatório com `documentNumber` se omitir `fullName`. Um CPF sem nome também exige `dateOfBirth`.", "`fullName`을 생략하면 `documentNumber`와 함께 필수입니다. 이름 없는 CPF는 `dateOfBirth`도 필요합니다.", "`fullName` を省くと `documentNumber` とセットで必須です。氏名のない CPF は `dateOfBirth` も必要です。", "省略 `fullName` 时必须与 `documentNumber` 一起发送。无姓名的 CPF 还需要 `dateOfBirth`。") },
	{ name: "documentNumber", type: "string", req: "cond", example: "12345678901", desc: T("Identifier of at least 5 characters, sent with `documentType` when `fullName` is omitted.", "Identificador de al menos 5 caracteres, con `documentType`, si omite `fullName`.", "Identifiant d'au moins 5 caractères, avec `documentType`, si `fullName` est omis.", "Identificador de pelo menos 5 caracteres, com `documentType`, se omitir `fullName`.", "`fullName`을 생략하면 `documentType`과 함께 보내는 5자 이상 식별자.", "`fullName` を省くとき `documentType` と一緒に送る 5文字以上の識別子。", "省略 `fullName` 时与 `documentType` 一起发送的至少 5 个字符的标识。") },
	{ name: "dateOfBirth", type: "string", req: "cond", example: "1990-01-15", desc: T("Required for CPF, CI, CCPA, DUI, or CCUY when `fullName` is omitted.", "Obligatoria para CPF, CI, CCPA, DUI o CCUY si omite `fullName`.", "Obligatoire pour CPF, CI, CCPA, DUI ou CCUY si `fullName` est omis.", "Obrigatória para CPF, CI, CCPA, DUI ou CCUY se omitir `fullName`.", "`fullName`을 생략하고 CPF, CI, CCPA, DUI, CCUY일 때 필수입니다.", "`fullName` を省き CPF、CI、CCPA、DUI、CCUY のとき必須です。", "省略 `fullName` 且为 CPF、CI、CCPA、DUI 或 CCUY 时必填。") },
];

const watch = (file, api, code, key, title, what, exampleName) =>
	page({
		file,
		method: "GET",
		apiPath: api,
		code,
		group: "watch",
		example: { fullName: exampleName },
		sample: { fullName: exampleName, [key]: true, details: { listName: title.en } },
		noMatch: { fullName: "CLEAN SAMPLE", [key]: false, details: {} },
		missingMessage: "missing fullName or documentType|documentNumber",
		params: watchP,
		title,
		sidebar: title,
		description: what,
		intro: what,
		after: T(
			`A match sets \`${key}\` to true and fills \`details\`. A subject who is not on the list is HTTP 200 with \`${key}\` false and empty \`details\`.`,
			`Una coincidencia pone \`${key}\` en true y llena \`details\`. Quien no está en la lista es HTTP 200 con \`${key}\` en false y \`details\` vacío.`,
			`Une correspondance met \`${key}\` à true et remplit \`details\`. Un sujet absent de la liste est un HTTP 200 avec \`${key}\` à false et \`details\` vide.`,
			`Uma correspondência põe \`${key}\` em true e preenche \`details\`. Quem não está na lista é HTTP 200 com \`${key}\` false e \`details\` vazio.`,
			`일치하면 \`${key}\`가 true이고 \`details\`가 채워집니다. 목록에 없으면 HTTP 200이고 \`${key}\`는 false이며 \`details\`는 비어 있습니다.`,
			`一致すると \`${key}\` は true で \`details\` が埋まります。一覧に無い対象は HTTP 200 で \`${key}\` は false、\`details\` は空です。`,
			`命中时 \`${key}\` 为 true 并填写 \`details\`。不在名单上是 HTTP 200，\`${key}\` 为 false，\`details\` 为空。`,
		),
		fields: B(
			[`\`${key}\``, "`details` on a match", "`fullName`"],
			[`\`${key}\``, "`details` en una coincidencia", "`fullName`"],
			[`\`${key}\``, "`details` en cas de correspondance", "`fullName`"],
			[`\`${key}\``, "`details` numa correspondência", "`fullName`"],
			[`\`${key}\``, "일치 시 `details`", "`fullName`"],
			[`\`${key}\``, "一致時の `details`", "`fullName`"],
			[`\`${key}\``, "命中时的 `details`", "`fullName`"],
		),
		uses: B(
			["Screen before you pay or onboard.", "Treat a false flag as a clean 200.", "Send a name, or a document type plus number."],
			["Criba antes de pagar o dar de alta.", "Trate una bandera false como un 200 limpio.", "Envíe un nombre, o tipo y número de documento."],
			["Filtrez avant de payer ou d'entrer en relation.", "Traitez un indicateur false comme un 200 net.", "Envoyez un nom, ou un type et un numéro."],
			["Filtre antes de pagar ou admitir.", "Trate uma bandeira false como um 200 limpo.", "Envie um nome, ou tipo e número."],
			["지급이나 온보딩 전에 대조합니다.", "false 플래그를 깨끗한 200으로 다룹니다.", "이름, 또는 문서 유형과 번호를 보냅니다."],
			["支払いや受付の前に照合します。", "false のフラグをきれいな 200 として扱います。", "名前、または文書種別と番号を送ります。"],
			["付款或准入前筛查。", "把 false 标志当作干净的 200。", "发送名称，或证件类型加号码。"],
		),
		notes: B(
			["Send `fullName`, or both `documentType` and `documentNumber`.", `A person or address that is not listed is HTTP 200 with \`${key}\` false.`, "CPF without a name also needs `dateOfBirth`."],
			["Envíe `fullName`, o `documentType` y `documentNumber`.", `Quien no está listado es HTTP 200 con \`${key}\` en false.`, "Un CPF sin nombre también exige `dateOfBirth`."],
			["Envoyez `fullName`, ou `documentType` et `documentNumber`.", `Un sujet non listé est un HTTP 200 avec \`${key}\` à false.`, "Un CPF sans nom exige aussi `dateOfBirth`."],
			["Envie `fullName`, ou `documentType` e `documentNumber`.", `Quem não está listado é HTTP 200 com \`${key}\` false.`, "Um CPF sem nome também exige `dateOfBirth`."],
			["`fullName`, 또는 `documentType`과 `documentNumber`를 보냅니다.", `미등재는 \`${key}\`가 false인 HTTP 200입니다.`, "이름 없는 CPF는 `dateOfBirth`도 필요합니다."],
			["`fullName`、または `documentType` と `documentNumber` を送ります。", `未掲載は \`${key}\` が false の HTTP 200 です。`, "氏名のない CPF は `dateOfBirth` も必要です。"],
			["发送 `fullName`，或同时发送 `documentType` 与 `documentNumber`。", `未列入是 HTTP 200，且 \`${key}\` 为 false。`, "无姓名的 CPF 还需要 `dateOfBirth`。"],
		),
		sandParams: [`\`fullName: "${exampleName}"\``, "Omit fullName and the document pair", '`fullName: "CLEAN SAMPLE"`'],
		sandResults: found(key),
	});

