		sandResults: T(["200 with province, canton, parish, and junta.", "409 MissingParameter.", "404 NotFound when the padrón has no row."], ["200 con provincia, cantón, parroquia y junta.", "409 MissingParameter.", "404 NotFound si el padrón no tiene fila."], ["200 avec province, canton, paroisse et junta.", "409 MissingParameter.", "404 NotFound si le padrón n'a pas de ligne."], ["200 com província, cantão, paróquia e junta.", "409 MissingParameter.", "404 NotFound se o padrón não tiver linha."], ["주, 칸톤, 교구, 준타가 있는 200.", "409 MissingParameter.", "명부에 행이 없으면 404 NotFound."], ["県、カントン、教区、フンタのある 200。", "409 MissingParameter。", "名簿に行が無いと 404 NotFound。"], ["含省、县、堂区和投票组的 200。", "409 MissingParameter。", "名册没有记录时为 404 NotFound。"]),
